const input = $input.first()?.json ?? {};
for (const field of ['run_id', 'history_id', 'step_key', 'step_title', 'project_question']) {
  if (typeof input[field] !== 'string' || !input[field].trim()) throw new Error('missing required field: ' + field);
}
if (!/^[0-9a-f-]{36}$/i.test(input.run_id)) throw new Error('run_id must be a UUID');
const stepOrder = Number(input.step_order);
if (!Number.isInteger(stepOrder) || stepOrder < 1 || stepOrder > 11) throw new Error('step_order must be between 1 and 11');
const candidate = input.existing_output && typeof input.existing_output === 'object' ? input.existing_output : null;
const keys = candidate ? Object.keys(candidate).sort() : [];
const content = String(candidate?.content ?? '').trim();
const reusable = candidate
  && JSON.stringify(keys) === JSON.stringify(['citations', 'content', 'title', 'unit_id'])
  && String(candidate.unit_id ?? '').trim() === input.step_key
  && String(candidate.title ?? '').trim() === input.step_title
  && content
  && !content.startsWith('无法生成本章节')
  && !content.startsWith('无法完成本章节')
  && Array.isArray(candidate.citations);
const existingOutput = reusable ? { unit_id: input.step_key, title: input.step_title, content, citations: candidate.citations } : null;
return [{ json: { ...input, step_order: stepOrder, existing_output: existingOutput } }];

