const state = $('Validate Step Request').first().json;
const result = $input.first()?.json ?? {};
if (result.error || result.detail) throw new Error('codex_harness_failed:' + String(result.error?.message ?? result.detail ?? result.error));
const keys = Object.keys(result).sort();
const expectedKeys = ['citations', 'content', 'title', 'unit_id'];
if (JSON.stringify(keys) !== JSON.stringify(expectedKeys)) throw new Error('strategy_chapter_contract_mismatch');
const unitId = String(result.unit_id ?? '').trim();
const title = String(result.title ?? '').trim();
const content = String(result.content ?? '').trim();
if (unitId !== state.step_key || title !== state.step_title || !content || !Array.isArray(result.citations)) throw new Error('strategy_chapter_identity_mismatch');
const output = { unit_id: unitId, title, content, citations: result.citations };
return [{ json: { result: { run_id: state.run_id, step_key: state.step_key, step_order: state.step_order, status: 'completed', output } } }];

