WITH payload AS (SELECT $1::jsonb AS value), saved_step AS (
  UPDATE analysis_step_outputs SET status = payload.value->>'status', output = payload.value->'output', citations = payload.value->'output'->'citations', diagnostics = '[]'::jsonb, updated_at = NOW()
  FROM payload WHERE run_id = (payload.value->>'run_id')::uuid AND step = payload.value->>'step_key' RETURNING run_id
), saved_run AS (
  UPDATE analysis_runs AS run SET current_step = payload.value->>'step_key', heartbeat_at = NOW(), lease_expires_at = NOW() + INTERVAL '6 hours', updated_at = NOW()
  FROM payload WHERE id = (payload.value->>'run_id')::uuid RETURNING id
) SELECT value AS result FROM payload;
